INSERT INTO public."Course" (course_id, title, description, price, created_by, created_at, updated_at, level, duration, cover_asset_id, image_url, deleted_at) VALUES
('20', 'Japanese Language Course N4', 'An N4 Japanese course focused on expanding vocabulary and grammar. This course helps students improve reading and listening comprehension skills for practical real-life situations. Students will also learn how to express opinions and emotions naturally.', '3000.00', '6', '2026-05-14 16:04:04.018332', '2026-05-22 00:28:41.692977', 'beginner', '300', '4', 'https://res.cloudinary.com/dawzi5py8/image/upload/v1779384517/jpmaster/courses/image/file_kvflqz.jpg', NULL),
('21', 'Intermediate Japanese Course N3', 'An intermediate-level Japanese course with extensive practical exercises. Students will strengthen grammar and vocabulary knowledge while improving communication confidence through group exercises and discussions.', '3000.00', '9', '2026-05-14 16:04:04.018332', '2026-05-22 00:28:51.931457', 'intermediate', '300', '5', 'https://res.cloudinary.com/dawzi5py8/image/upload/v1779384528/jpmaster/courses/image/file_qcgfq5.webp', NULL),
('22', 'JLPT N2 Preparation Course', 'A Japanese N2 preparation course designed for JLPT learners. Students will study advanced grammar topics, specialized vocabulary, and essential exam skills. The course also includes mock tests to familiarize students with the JLPT exam format.', '3000.00', '7', '2026-05-14 16:04:04.018332', '2026-05-22 00:29:57.228094', 'intermediate', '300', '9', 'https://res.cloudinary.com/dawzi5py8/image/upload/v1779384592/jpmaster/courses/image/file_cceukz.jpg', NULL),
('25', 'Free Japanese Communication Course', 'A free Japanese communication course designed to improve basic conversational skills through practical exercises and real-life situations. Students will learn self-introduction, asking for directions, and basic questioning techniques.', '0.00', '11', '2026-05-14 16:04:04.018332', '2026-05-24 12:56:42.893705', 'beginner', '180', '40', 'https://res.cloudinary.com/dawzi5py8/image/upload/v1779602197/jpmaster/courses/image/upload-1779602197837_a2h6gv.webp', NULL),
('19', 'Japanese for Beginners N5', 'A beginner Japanese course for N5 learners. In this course, students will learn Hiragana and Katakana, basic vocabulary, simple sentence structures, and essential communication skills for everyday situations.', '3000.00', '6', '2026-05-14 16:04:04.018332', '2026-05-22 00:29:08.844743', 'beginner', '300', '6', 'https://res.cloudinary.com/dawzi5py8/image/upload/v1779384545/jpmaster/courses/image/file_iyxcir.webp', NULL),
('24', 'Free Japanese Culture Course', 'A free course introducing Japanese culture, customs, and traditions. Students will explore Japanese festivals, cuisine, arts, and unique cultural practices.', '0.00', '10', '2026-05-14 16:04:04.018332', '2026-05-22 00:29:43.773446', 'beginner', '300', '8', 'https://res.cloudinary.com/dawzi5py8/image/upload/v1779384579/jpmaster/courses/image/file_kcnqnv.jpg', NULL),
('23', 'Advanced Japanese Course N1', 'An advanced Japanese course designed for learners aiming to achieve the highest Japanese proficiency level. Students will study advanced grammar, specialized vocabulary, and master listening, speaking, reading, and writing skills.', '3000.00', '8', '2026-05-14 16:04:04.018332', '2026-05-22 00:29:19.295071', 'advanced', '300', '7', 'https://res.cloudinary.com/dawzi5py8/image/upload/v1779384555/jpmaster/courses/image/file_j6wwfm.jpg', NULL);
