INSERT INTO public."Question" (question_id, question_text, question_type, created_at, updated_at, created_by, difficulty_level, explanation, points, jlpt_level, section_type, deleted_at, image_asset_id, image_url, audio_asset_id, audio_url, reading_passage_id) VALUES
('3', '「田中さんは とても（　）人です。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'easy', '親切 means kind and fits the sentence naturally.', '1.00', 'N5', 'vocabulary', NULL, NULL, NULL, NULL, NULL, NULL),
('5', '「このかばんは（　）ですから、買います。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'easy', '安い means cheap/inexpensive.', '1.00', 'N5', 'vocabulary', NULL, NULL, NULL, NULL, NULL, NULL),
('6', '「日曜日に 何をしましたか。」', 'multiple_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'medium', 'Both options describe correct past actions.', '1.00', 'N4', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('7', '「駅へ行く（　）、この道をまっすぐ行ってください。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'medium', 'には indicates purpose/direction.', '1.00', 'N4', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('8', '「この漢字の（　）を教えてください。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'medium', '読み means reading/pronunciation.', '1.00', 'N4', 'vocabulary', NULL, NULL, NULL, NULL, NULL, NULL),
('9', '「昨日は 雨が（　）、出かけませんでした。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'medium', '降っていた indicates ongoing rain in the past.', '1.00', 'N4', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('10', '「日本では 電車の中で（　）いけません。」', 'multiple_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'medium', 'Talking loudly and smoking are prohibited.', '1.00', 'N4', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('11', '「部長は ただ今（　）ございます。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', '席を外して is a polite business expression.', '1.00', 'N3', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('12', '「彼は 約束を（　）人だ。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', '守る means to keep a promise.', '1.00', 'N3', 'vocabulary', NULL, NULL, NULL, NULL, NULL, NULL),
('13', '「試験に合格する（　）、毎日勉強しています。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', 'ために expresses purpose.', '1.00', 'N3', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('14', '「この問題について、どう（　）ますか。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', '考え expresses opinion/thought.', '1.00', 'N3', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('15', '「日本語が上手になるには、たくさん（　）ことが大切です。」', 'multiple_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', 'Listening and speaking are both essential skills.', '1.00', 'N3', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('16', '「彼の説明は 分かり（　）。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', 'にくかった means difficult to understand.', '1.00', 'N2', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('17', '「社長のご意見は 大変（　）ものだった。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', '参考になる means informative/helpful.', '1.00', 'N2', 'vocabulary', NULL, NULL, NULL, NULL, NULL, NULL),
('18', '「このプロジェクトは 成功する（　）が高い。」', 'single_choice', '2026-05-17 21:05:05.591796', '2026-05-17 21:05:05.591796', NULL, 'hard', '可能性 means possibility.', '1.00', 'N2', 'grammar', NULL, NULL, NULL, NULL, NULL, NULL),
('19', '「次の文章を読んで、正しいものを選びなさい。
